import pandas as pd, numpy as np

class AlphaBase:
    window_length=20; inputs=["close"]
    def calc(self,data): pass

class MyAlpha(AlphaBase):
    def __init__(self):
        self.window_length=20
        self.inputs=["close"]

    def calc(self,data:dict)->pd.DataFrame:
        # Gán dữ liệu vào biến
        close  = data["close"].ffill().fillna(0)

        # Tính toán chuỗi tăng liên tục 3 phiên
        tăng_liên_tục = (close > close.shift(1)) * 1

        # Tính toán alpha sử dụng hàm tích lũy
        def tích_lũy(x):
            if len(x) < 3:
                return 0
            return np.sum(x[-3:])

        alpha = close.rolling(3, min_periods=1).apply(tích_lũy, raw=True)

        # Map signal từ 0 đến 1 sử dụng hàm sigmoid
        def sigmoid(x):
            return 1 / (1 + np.exp(-x))

        signal = sigmoid(alpha)

        # Chuẩn hóa rank
        signal = signal.rank(axis=1, pct=True) - 0.5

        return signal.reindex(index=close.index, columns=close.columns).fillna(0)
